package livox

import (
	"encoding/hex"
	"encoding/json"
	"strings"
	"testing"
)

// Frames generated by the Python reference implementation of the SDK2
// protocol; they pin the exact byte layout and both CRC algorithms.
const (
	fixtureQueryHex     = "aa0018000700000000000000000000000000ce1400000000"
	fixtureAckMid360Hex = "aa0030002a000000000001010000000000008d4c27473a8e" +
		"000954464432444a41414230303030310000c000020a24db"
	fixtureAckErrHex = "aa0030002b00000000000101000000000000ec3791aeb8cf" +
		"012331323334353637383930313233343536c000026388db"
)

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad hex fixture: %v", err)
	}
	return b
}

func TestBuildDiscoveryQueryMatchesReference(t *testing.T) {
	got, err := BuildDiscoveryQuery(7)
	if err != nil {
		t.Fatalf("BuildDiscoveryQuery: %v", err)
	}
	if want := mustHex(t, fixtureQueryHex); !equalBytes(got, want) {
		t.Errorf("query frame = %x, want %x", got, want)
	}
}

func TestBuildDiscoveryACKMatchesReference(t *testing.T) {
	payload, err := BuildDiscoveryPayload(9, "TFD2DJAAB00001", "192.0.2.10", 56100, 0)
	if err != nil {
		t.Fatalf("BuildDiscoveryPayload: %v", err)
	}
	got, err := BuildFrame(CmdIDDiscovery, CmdTypeAck, SenderTypeLidar, 42, payload, ProtocolVersion)
	if err != nil {
		t.Fatalf("BuildFrame: %v", err)
	}
	if want := mustHex(t, fixtureAckMid360Hex); !equalBytes(got, want) {
		t.Errorf("ack frame = %x, want %x", got, want)
	}
}

func TestParseDiscoveryACKReferenceFrames(t *testing.T) {
	tests := []struct {
		name     string
		frame    string
		want     DetectionData
		wantName string
		wantOK   bool
	}{
		{
			name:  "mid360 success",
			frame: fixtureAckMid360Hex,
			want: DetectionData{
				RetCode: 0,
				DevType: 9,
				SN:      "TFD2DJAAB00001",
				LidarIP: "192.0.2.10",
				CmdPort: 56100,
			},
			wantName: "Mid360",
			wantOK:   true,
		},
		{
			name:  "mid360s error code, sn padded to 16",
			frame: fixtureAckErrHex,
			want: DetectionData{
				RetCode: 1,
				DevType: 35,
				SN:      "1234567890123456",
				LidarIP: "192.0.2.99",
				CmdPort: 56200,
			},
			wantName: "Mid360S",
			wantOK:   false,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := ParseDiscoveryACK(mustHex(t, tt.frame))
			if err != nil {
				t.Fatalf("ParseDiscoveryACK: %v", err)
			}
			if got != tt.want {
				t.Errorf("detection = %+v, want %+v", got, tt.want)
			}
			if name := got.DevTypeName(); name != tt.wantName {
				t.Errorf("DevTypeName() = %q, want %q", name, tt.wantName)
			}
			if got.OK() != tt.wantOK {
				t.Errorf("OK() = %v, want %v", got.OK(), tt.wantOK)
			}
		})
	}
}

func TestDiscoveryPayloadRoundTrip(t *testing.T) {
	tests := []struct {
		name     string
		devType  byte
		sn       string
		lidarIP  string
		cmdPort  uint16
		retCode  byte
		wantName string
	}{
		{"mid360", 9, "TFD2DJAAB00001", "192.0.2.10", 56100, 0, "Mid360"},
		{"mid360s full sn", 35, "1234567890123456", "198.51.100.7", 56200, 0, "Mid360S"},
		{"avia2", 40, "SN1", "203.0.113.254", 56000, 0, "Avia2"},
		{"mid360l error ack", 41, "SN2", "192.0.2.1", 56101, 7, "Mid360L"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			payload, err := BuildDiscoveryPayload(tt.devType, tt.sn, tt.lidarIP, tt.cmdPort, tt.retCode)
			if err != nil {
				t.Fatalf("BuildDiscoveryPayload: %v", err)
			}
			if len(payload) != DetectionPayloadLen {
				t.Fatalf("payload length = %d, want %d", len(payload), DetectionPayloadLen)
			}
			got, err := ParseDiscoveryPayload(payload)
			if err != nil {
				t.Fatalf("ParseDiscoveryPayload: %v", err)
			}
			want := DetectionData{
				RetCode: tt.retCode,
				DevType: tt.devType,
				SN:      tt.sn,
				LidarIP: tt.lidarIP,
				CmdPort: tt.cmdPort,
			}
			if got != want {
				t.Errorf("detection = %+v, want %+v", got, want)
			}
			if name := got.DevTypeName(); name != tt.wantName {
				t.Errorf("DevTypeName() = %q, want %q", name, tt.wantName)
			}
		})
	}
}

func TestBuildDiscoveryPayloadErrors(t *testing.T) {
	tests := []struct {
		name    string
		devType byte
		sn      string
		lidarIP string
		wantErr string
	}{
		{"sn too long", 9, "12345678901234567", "192.0.2.1", "sn too long"},
		{"sn at the limit is fine", 9, "1234567890123456", "192.0.2.1", ""},
		{"malformed ip", 9, "SN", "999.1.2.3", "invalid IPv4"},
		{"not an ip", 9, "SN", "livox", "invalid IPv4"},
		{"ipv6 rejected", 9, "SN", "::1", "invalid IPv4"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := BuildDiscoveryPayload(tt.devType, tt.sn, tt.lidarIP, 56100, 0)
			if tt.wantErr == "" {
				if err != nil {
					t.Errorf("error = %v, want nil", err)
				}
				return
			}
			if err == nil || !strings.Contains(err.Error(), tt.wantErr) {
				t.Errorf("error = %v, want one containing %q", err, tt.wantErr)
			}
		})
	}
}

func TestParseDiscoveryPayloadErrors(t *testing.T) {
	valid := make([]byte, DetectionPayloadLen)
	tests := []struct {
		name    string
		payload []byte
	}{
		{"one byte short", valid[:DetectionPayloadLen-1]},
		{"one byte long", append(append([]byte(nil), valid...), 0)},
		{"empty", nil},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, err := ParseDiscoveryPayload(tt.payload); err == nil {
				t.Errorf("ParseDiscoveryPayload(%d bytes) = nil error, want length error", len(tt.payload))
			}
		})
	}
}

func TestParseDiscoveryACKNonDiscoveryCmd(t *testing.T) {
	frame, err := BuildFrame(0x0002, CmdTypeAck, SenderTypeLidar, 1, nil, ProtocolVersion)
	if err != nil {
		t.Fatalf("BuildFrame: %v", err)
	}
	if _, err := ParseDiscoveryACK(frame); err == nil || !strings.Contains(err.Error(), "not a discovery frame") {
		t.Errorf("error = %v, want not-a-discovery-frame", err)
	}
}

func TestDevTypeName(t *testing.T) {
	tests := []struct {
		devType byte
		want    string
	}{
		{9, "Mid360"},
		{35, "Mid360S"},
		{40, "Avia2"},
		{41, "Mid360L"},
		{0, "unknown(0)"},
		{255, "unknown(255)"},
	}
	for _, tt := range tests {
		if got := DevTypeName(tt.devType); got != tt.want {
			t.Errorf("DevTypeName(%d) = %q, want %q", tt.devType, got, tt.want)
		}
	}
}

func TestDetectionDataMarshalJSON(t *testing.T) {
	det := DetectionData{RetCode: 0, DevType: 9, SN: "TFD2DJAAB00001", LidarIP: "192.0.2.10", CmdPort: 56100}
	b, err := json.Marshal(det)
	if err != nil {
		t.Fatalf("Marshal: %v", err)
	}
	var m map[string]any
	if err := json.Unmarshal(b, &m); err != nil {
		t.Fatalf("Unmarshal: %v", err)
	}
	for _, key := range []string{"ret_code", "dev_type", "dev_type_name", "sn", "lidar_ip", "cmd_port"} {
		if _, ok := m[key]; !ok {
			t.Errorf("json %s missing key %q", b, key)
		}
	}
	if m["dev_type_name"] != "Mid360" {
		t.Errorf("dev_type_name = %v, want Mid360", m["dev_type_name"])
	}
}

func TestParseDiscoveryACKSanitizesSN(t *testing.T) {
	// SN field: "SN-OK", then a middle NUL and control/8-bit bytes (all
	// replaced by '?'), then NUL padding (trimmed).
	payload := make([]byte, DetectionPayloadLen)
	payload[detRetCodeOff] = 0
	payload[detDevTypeOff] = 9
	copy(payload[detSNOff:], "SN-OK")
	copy(payload[detSNOff+5:], []byte{0x00, 0x01, 0xE2, 0x80, 0x93})
	frame, err := BuildFrame(CmdIDDiscovery, CmdTypeAck, SenderTypeLidar, 1, payload, ProtocolVersion)
	if err != nil {
		t.Fatalf("BuildFrame: %v", err)
	}
	det, err := ParseDiscoveryACK(frame)
	if err != nil {
		t.Fatalf("ParseDiscoveryACK: %v", err)
	}
	if want := "SN-OK?????"; det.SN != want {
		t.Errorf("SN = %q, want %q", det.SN, want)
	}
}

func equalBytes(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
